"""ex03 规则版工具路由决策树：冲突则澄清，危险工具需人工确认。"""

ROUTES = [
    ("search_web", ("最新", "新闻", "今天", "实时", "搜索")),
    ("query_db", ("订单", "表", "查询数据库", "用户 id")),
    ("send_email", ("发送邮件", "通知", "抄送")),
    ("calculator", ("计算", "求和", "百分比", "+", "*")),
]

DANGEROUS = {"send_email"}   # 破坏性/外发类：需人工确认


def route(text):
    hits = [name for name, kws in ROUTES if any(k in text for k in kws)]
    if len(hits) == 1:
        need_confirm = hits[0] in DANGEROUS
        return hits[0], ("需人工确认" if need_confirm else "直接执行")
    if len(hits) > 1:
        return None, "意图冲突(%s)，先向用户澄清" % "/".join(hits)
    return None, "无匹配工具，转人工或回答能力边界"


CASES = [
    "帮我搜一下今天的最新新闻",
    "查询 订单 表里用户 id=7 的记录",
    "给老板发送邮件通知结果",
    "计算 12 的 15% 是多少",
    "计算并发送邮件通知结果",
    "讲个笑话",
]

if __name__ == "__main__":
    clarify_n = 0
    for c in CASES:
        tool, how = route(c)
        if tool is None:
            clarify_n += 1
        print("%s => %s | %s" % (c, tool or "NONE", how))
    print("未直接执行（澄清/升级）的请求数 = %d" % clarify_n)
